signedchar BME280_I2C_bus_read(unsignedchar device_addr, unsignedchar
reg_addr, unsignedchar *reg_data, unsignedchar cnt)
{
int iError=0;
unsignedchararray[I2C_BUFFER_LEN];
unsignedchar stringpos;
array[0] = reg_addr;
iError = I2C_write_read_string(I2C0, device_addr, array, array, 1, cnt);
for(stringpos=0;stringpos<cnt;stringpos++)
{
*(reg_data + stringpos) = array[stringpos];
}
return (signedchar)iError;
}
signedchar BME280_I2C_bus_write(unsignedchar device_addr, unsignedchar
reg_addr, unsignedchar *reg_data, unsignedchar cnt)
{
int iError=0;
unsignedchar array[I2C_BUFFER_LEN];
unsignedchar stringpos;
array[0] = reg_addr;
for(stringpos=0;stringpos<cnt;stringpos++)
{
array[stringpos+1] = *(reg_data + stringpos);
}
iError = I2C_write_string(I2C0, device_addr, array, cnt+1);
return (signedchar)iError;
}
